      const tenant=await tx.tenant.findUniqueOrThrow({where:{id:a.tenantId}});const currencies=await tx.currency.findMany({where:{tenantId:a.tenantId,code:{in:[currency,tenant.baseCurrency]},active:true}});if(!currencies.some(c=>c.code===currency)||!currencies.some(c=>c.code===tenant.baseCurrency))fail('Payment and base currencies must be supported and active');const originalPrecision=currencies.find(c=>c.code===currency)?.precision??2,basePrecision=currencies.find(c=>c.code===tenant.baseCurrency)?.precision??2;let grossMinor:bigint,feeMinor:bigint;try{grossMinor=currencyAmount(b.amount,originalPrecision);feeMinor=currencyAmount(b.feeAmount||'0',originalPrecision);}catch{failField('amount','Enter an exact amount using the selected currency precision');}if(grossMinor<=0n||feeMinor<0n||feeMinor>=grossMinor)failField('feeAmount','Fees must be nonnegative and less than the gross payment');if(feeMinor>0n&&!preparedFile)failField('attachment','Attach evidence showing the gross payment, bank fee and net credit');if(feeMinor>0n&&b.feeTreatment!=='DEDUCTED_BY_BANK')failField('feeTreatment','Select the documented bank-deducted fee treatment');const amountMinor=grossMinor-feeMinor;const rates=await this.receiptRates(tx,a,currency,paymentDate,b.usdToBaseRate);
