      const refundInstructions=await tx.av8Fund.findMany({where:{tenantId:a.tenantId,applicationId:{in:apps.map(x=>x.id)},kind:'REFUND',status:{in:['PENDING','APPROVED','CLEARED']}}});const servicePayments=await tx.av8Record.findMany({where:{tenantId:a.tenantId,applicationId:{in:apps.map(x=>x.id)},kind:'service-payment',status:'RECORDED'}});const availability=(fund:any)=>{if(fund.kind!=='RECEIPT')return {};const reserved=refundInstructions.flatMap(f=>(f.metadata as any).originalReceiptAllocations||[]).filter((x:any)=>String(x.fundId)===String(fund.id)&&!x.chargeId).reduce((n:bigint,x:any)=>n+BigInt(x.usdMinor),0n),services=servicePayments.filter(r=>(r.data as any).collectionParty==='AV8'&&String((r.data as any).fundId)===String(fund.id)).reduce((n,r)=>n+BigInt((r.data as any).usdMinor),0n);return {reservedRefundUsdMinor:reserved,availableUsdMinor:returnedIds.includes(fund.id)?0n:BigInt(fund.usdMinor)-BigInt(fund.allocations.reduce((n:bigint,x:any)=>n+BigInt(x.amountMinor),0n))-services-reserved};};
